// PhotoFrame.js
import React, { useRef, useState, useEffect } from 'react';

const PhotoFrame = ({ photo, userName, location }) => {
  const canvasRef = useRef(null);
  const [photoUrl, setPhotoUrl] = useState(null);
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    if (photo) {
      const url = URL.createObjectURL(photo);
      setPhotoUrl(url);
      return () => URL.revokeObjectURL(url);
    }
  }, [photo]);

  useEffect(() => {
    if (photoUrl) {
      drawFrame();
    }
  }, [photoUrl, userName, location]);

  const drawFrame = async () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    const W = 1080;
    const H = 1320;
    canvas.width = W;
    canvas.height = H;

    // Colors
    const GREEN = '#0d5d36';
    const DARK_GREEN = '#08442a';
    const GOLD = '#c9a24a';
    const GOLD_LIGHT = '#e8c97a';
    const GOLD_DARK = '#9c7a2e';
    const CREAM = '#fdfaf2';

    // ---------- BACKGROUND ----------
    ctx.fillStyle = CREAM;
    ctx.fillRect(0, 0, W, H);

    // ---------- OUTER GREEN CURVED FRAME ----------
    // Top-left and top-right green corners (curved)
    const drawCornerGreen = () => {
      ctx.fillStyle = GREEN;
      // Top band
      ctx.fillRect(0, 0, W, 60);
      // Left band
      ctx.fillRect(0, 0, 60, H);
      // Right band
      ctx.fillRect(W - 60, 0, 60, H);
      // Bottom band thicker
      ctx.fillRect(0, H - 220, W, 220);
    };

    // Use a clipping path to create rounded inner cream area with arched top
    ctx.save();
    // Fill entire with green first
    const grad = ctx.createLinearGradient(0, 0, 0, H);
    grad.addColorStop(0, GREEN);
    grad.addColorStop(1, DARK_GREEN);
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W, H);

    // Inner cream shape with arched top corners
    ctx.fillStyle = CREAM;
    ctx.beginPath();
    const inset = 55;
    const archRadius = 280;
    ctx.moveTo(inset, archRadius);
    ctx.quadraticCurveTo(inset, inset, archRadius, inset);
    ctx.lineTo(W - archRadius, inset);
    ctx.quadraticCurveTo(W - inset, inset, W - inset, archRadius);
    ctx.lineTo(W - inset, H - 240);
    ctx.quadraticCurveTo(W / 2, H - 140, inset, H - 240);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // ---------- GOLD BORDERS ----------
    // Outer gold thin line
    ctx.strokeStyle = GOLD;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(inset + 12, archRadius);
    ctx.quadraticCurveTo(inset + 12, inset + 12, archRadius, inset + 12);
    ctx.lineTo(W - archRadius, inset + 12);
    ctx.quadraticCurveTo(W - inset - 12, inset + 12, W - inset - 12, archRadius);
    ctx.lineTo(W - inset - 12, H - 250);
    ctx.quadraticCurveTo(W / 2, H - 155, inset + 12, H - 250);
    ctx.closePath();
    ctx.stroke();

    // Inner gold thicker decorative line
    const goldGrad = ctx.createLinearGradient(0, 0, W, 0);
    goldGrad.addColorStop(0, GOLD_DARK);
    goldGrad.addColorStop(0.5, GOLD_LIGHT);
    goldGrad.addColorStop(1, GOLD_DARK);
    ctx.strokeStyle = goldGrad;
    ctx.lineWidth = 6;
    ctx.beginPath();
    ctx.moveTo(inset + 28, archRadius);
    ctx.quadraticCurveTo(inset + 28, inset + 28, archRadius, inset + 28);
    ctx.lineTo(W - archRadius, inset + 28);
    ctx.quadraticCurveTo(W - inset - 28, inset + 28, W - inset - 28, archRadius);
    ctx.lineTo(W - inset - 28, H - 265);
    ctx.quadraticCurveTo(W / 2, H - 175, inset + 28, H - 265);
    ctx.closePath();
    ctx.stroke();

    // ---------- BOTTOM GOLD CURVE DECORATION ----------
    ctx.strokeStyle = goldGrad;
    ctx.lineWidth = 8;
    ctx.beginPath();
    ctx.moveTo(80, H - 200);
    ctx.quadraticCurveTo(W / 2, H - 70, W - 80, H - 200);
    ctx.stroke();

    ctx.strokeStyle = GOLD_LIGHT;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(100, H - 195);
    ctx.quadraticCurveTo(W / 2, H - 80, W - 100, H - 195);
    ctx.stroke();

    // ---------- 100 YEARS LOGO TOP ----------
    drawHundredYearsLogo(ctx, W / 2, 175, GREEN, GOLD, GOLD_LIGHT, GOLD_DARK);

    // ---------- LOCATION TITLE ----------
    ctx.fillStyle = DARK_GREEN;
    ctx.font = 'bold 64px "Times New Roman", serif';
    ctx.textAlign = 'center';
    ctx.fillText(location || 'Location', W / 2, 410);

    // Decorative line under title
    drawOrnamentLine(ctx, W / 2, 445, 320, GOLD);

    // ---------- CIRCULAR PHOTO ----------
    const cx = W / 2;
    const cy = 720;
    const photoR = 230;

    // Outer gold ring (double)
    ctx.strokeStyle = GOLD;
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(cx, cy, photoR + 30, 0, Math.PI * 2);
    ctx.stroke();

    // Dotted gold ring
    ctx.strokeStyle = GOLD_DARK;
    ctx.lineWidth = 2;
    ctx.setLineDash([2, 8]);
    ctx.beginPath();
    ctx.arc(cx, cy, photoR + 20, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);

    // Green ring
    ctx.strokeStyle = GREEN;
    ctx.lineWidth = 10;
    ctx.beginPath();
    ctx.arc(cx, cy, photoR + 8, 0, Math.PI * 2);
    ctx.stroke();

    // Inner gold
    ctx.strokeStyle = GOLD_LIGHT;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(cx, cy, photoR + 2, 0, Math.PI * 2);
    ctx.stroke();

    // Photo clip
    if (photoUrl) {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        ctx.save();
        ctx.beginPath();
        ctx.arc(cx, cy, photoR, 0, Math.PI * 2);
        ctx.closePath();
        ctx.clip();

        // cover-fit
        const ratio = Math.max((photoR * 2) / img.width, (photoR * 2) / img.height);
        const dw = img.width * ratio;
        const dh = img.height * ratio;
        ctx.drawImage(img, cx - dw / 2, cy - dh / 2, dw, dh);
        ctx.restore();

        // Decorative ornaments left & right of photo
        drawSideOrnament(ctx, cx - photoR - 35, cy, GOLD);
        drawSideOrnament(ctx, cx + photoR + 35, cy, GOLD);

        // Continue rest
        finishDrawing();
      };
      img.src = photoUrl;
    } else {
      finishDrawing();
    }

    function finishDrawing() {
      // ---------- GIFT OF READING RIBBON ----------
      const ribbonY = 1010;
      const ribbonW = 540;
      const ribbonH = 90;
      const rx = W / 2 - ribbonW / 2;

      // Ribbon tails (left)
      ctx.fillStyle = DARK_GREEN;
      ctx.beginPath();
      ctx.moveTo(rx - 60, ribbonY + 15);
      ctx.lineTo(rx + 20, ribbonY + 10);
      ctx.lineTo(rx + 20, ribbonY + ribbonH);
      ctx.lineTo(rx - 60, ribbonY + ribbonH + 25);
      ctx.lineTo(rx - 30, ribbonY + (ribbonH + 25) / 2);
      ctx.closePath();
      ctx.fill();

      // Ribbon tails (right)
      ctx.beginPath();
      ctx.moveTo(rx + ribbonW + 60, ribbonY + 15);
      ctx.lineTo(rx + ribbonW - 20, ribbonY + 10);
      ctx.lineTo(rx + ribbonW - 20, ribbonY + ribbonH);
      ctx.lineTo(rx + ribbonW + 60, ribbonY + ribbonH + 25);
      ctx.lineTo(rx + ribbonW + 30, ribbonY + (ribbonH + 25) / 2);
      ctx.closePath();
      ctx.fill();

      // Main ribbon body
      ctx.fillStyle = GREEN;
      roundRect(ctx, rx, ribbonY, ribbonW, ribbonH, 6);
      ctx.fill();

      // Gold border on ribbon
      ctx.strokeStyle = GOLD_LIGHT;
      ctx.lineWidth = 3;
      roundRect(ctx, rx + 8, ribbonY + 8, ribbonW - 16, ribbonH - 16, 4);
      ctx.stroke();

      // Ribbon text
      ctx.fillStyle = CREAM;
      ctx.font = 'bold 50px "Georgia", serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('• Gift of Reading •', W / 2, ribbonY + ribbonH / 2);
      ctx.textBaseline = 'alphabetic';

      // ---------- PRESENTED BY ----------
      ctx.fillStyle = '#444';
      ctx.font = '28px "Georgia", serif';
      ctx.textAlign = 'center';
      ctx.fillText('Presented by', W / 2, 1170);

      ctx.fillStyle = DARK_GREEN;
      ctx.font = '32px "Georgia", serif';
      ctx.fillText(location || 'Location', W / 2, 1210);

      // Small ornament line
      drawOrnamentLine(ctx, W / 2, 1240, 200, GOLD);

      // ---------- USER NAME ----------
      ctx.fillStyle = DARK_GREEN;
      ctx.font = 'bold 42px "Georgia", serif';
      ctx.fillText(userName || 'Participant', W / 2, 1290);

      // ---------- BOTTOM BOOK ICON ----------
      drawBookIcon(ctx, W / 2, H - 75, GOLD, GOLD_LIGHT);

      setIsReady(true);
    }
  };

  // ---------- HELPERS ----------
  const drawHundredYearsLogo = (ctx, cx, cy, green, gold, goldLight, goldDark) => {
    // Stars on top
    ctx.fillStyle = gold;
    [-1, 0, 1].forEach((i) => {
      drawStar(ctx, cx + i * 30, cy - 110, 8, gold);
    });

    // "100" text
    ctx.fillStyle = green;
    ctx.font = 'bold 110px "Georgia", serif';
    ctx.textAlign = 'center';
    ctx.fillText('100', cx, cy);

    // Book icon inside the 0 (between zeros)
    drawSmallBook(ctx, cx + 4, cy - 38, gold, goldLight);

    // Laurel wreath left
    drawLaurel(ctx, cx - 130, cy, gold, false);
    // Laurel wreath right
    drawLaurel(ctx, cx + 130, cy, gold, true);

    // YEARS banner
    ctx.fillStyle = green;
    ctx.font = 'bold 22px "Georgia", serif';
    ctx.fillText('YEARS', cx, cy + 30);

    // CELEBRATION ribbon
    const ribW = 200;
    const ribH = 32;
    const rx = cx - ribW / 2;
    const ry = cy + 45;

    ctx.fillStyle = gold;
    ctx.beginPath();
    ctx.moveTo(rx, ry);
    ctx.lineTo(rx + ribW, ry);
    ctx.lineTo(rx + ribW + 15, ry + ribH / 2);
    ctx.lineTo(rx + ribW, ry + ribH);
    ctx.lineTo(rx, ry + ribH);
    ctx.lineTo(rx - 15, ry + ribH / 2);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = '#fff';
    ctx.font = 'bold 18px "Georgia", serif';
    ctx.textBaseline = 'middle';
    ctx.fillText('CELEBRATION', cx, ry + ribH / 2);
    ctx.textBaseline = 'alphabetic';

    // Small ornament under
    drawOrnamentLine(ctx, cx, cy + 95, 150, gold);
  };

  const drawSmallBook = (ctx, cx, cy, gold, goldLight) => {
    ctx.fillStyle = gold;
    // Book base
    ctx.beginPath();
    ctx.moveTo(cx - 35, cy);
    ctx.lineTo(cx, cy - 18);
    ctx.lineTo(cx + 35, cy);
    ctx.lineTo(cx, cy + 12);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = goldLight;
    ctx.beginPath();
    ctx.moveTo(cx - 30, cy - 2);
    ctx.lineTo(cx, cy - 14);
    ctx.lineTo(cx + 30, cy - 2);
    ctx.lineTo(cx, cy + 8);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = gold;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(cx, cy - 14);
    ctx.lineTo(cx, cy + 8);
    ctx.stroke();
  };

  const drawLaurel = (ctx, cx, cy, color, mirror) => {
    ctx.save();
    ctx.translate(cx, cy);
    if (mirror) ctx.scale(-1, 1);
    ctx.fillStyle = color;
    // Curved stem
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, -90);
    ctx.quadraticCurveTo(-50, 0, 0, 90);
    ctx.stroke();

    // Leaves
    for (let i = -80; i <= 80; i += 18) {
      const t = (i + 80) / 160;
      const x = -Math.sin(t * Math.PI) * 50;
      ctx.save();
      ctx.translate(x, i);
      ctx.rotate(-Math.PI / 4);
      ctx.beginPath();
      ctx.ellipse(-8, 0, 12, 5, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();
  };

  const drawStar = (ctx, cx, cy, r, color) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    for (let i = 0; i < 5; i++) {
      const angle = (Math.PI * 2 * i) / 5 - Math.PI / 2;
      const x = cx + Math.cos(angle) * r;
      const y = cy + Math.sin(angle) * r;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
      const angle2 = angle + Math.PI / 5;
      const x2 = cx + Math.cos(angle2) * (r / 2);
      const y2 = cy + Math.sin(angle2) * (r / 2);
      ctx.lineTo(x2, y2);
    }
    ctx.closePath();
    ctx.fill();
  };

  const drawOrnamentLine = (ctx, cx, cy, width, color) => {
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(cx - width / 2, cy);
    ctx.lineTo(cx - 15, cy);
    ctx.moveTo(cx + 15, cy);
    ctx.lineTo(cx + width / 2, cy);
    ctx.stroke();

    // center diamond
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(cx, cy - 5);
    ctx.lineTo(cx + 5, cy);
    ctx.lineTo(cx, cy + 5);
    ctx.lineTo(cx - 5, cy);
    ctx.closePath();
    ctx.fill();

    // side dots
    ctx.beginPath();
    ctx.arc(cx - 12, cy, 2, 0, Math.PI * 2);
    ctx.arc(cx + 12, cy, 2, 0, Math.PI * 2);
    ctx.fill();
  };

  const drawSideOrnament = (ctx, cx, cy, color) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(cx, cy - 10);
    ctx.lineTo(cx + 8, cy);
    ctx.lineTo(cx, cy + 10);
    ctx.lineTo(cx - 8, cy);
    ctx.closePath();
    ctx.fill();

    ctx.beginPath();
    ctx.arc(cx, cy - 14, 2.5, 0, Math.PI * 2);
    ctx.arc(cx, cy + 14, 2.5, 0, Math.PI * 2);
    ctx.fill();
  };

  const drawBookIcon = (ctx, cx, cy, gold, goldLight) => {
    ctx.fillStyle = gold;
    ctx.beginPath();
    ctx.moveTo(cx - 60, cy - 20);
    ctx.lineTo(cx, cy - 30);
    ctx.lineTo(cx + 60, cy - 20);
    ctx.lineTo(cx + 60, cy + 25);
    ctx.lineTo(cx, cy + 18);
    ctx.lineTo(cx - 60, cy + 25);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = goldLight;
    ctx.beginPath();
    ctx.moveTo(cx - 55, cy - 16);
    ctx.lineTo(cx, cy - 25);
    ctx.lineTo(cx + 55, cy - 16);
    ctx.lineTo(cx + 55, cy + 18);
    ctx.lineTo(cx, cy + 12);
    ctx.lineTo(cx - 55, cy + 18);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = gold;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(cx, cy - 25);
    ctx.lineTo(cx, cy + 12);
    ctx.stroke();

    // small flourish on sides
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(cx - 100, cy + 5);
    ctx.quadraticCurveTo(cx - 80, cy - 5, cx - 65, cy + 5);
    ctx.moveTo(cx + 100, cy + 5);
    ctx.quadraticCurveTo(cx + 80, cy - 5, cx + 65, cy + 5);
    ctx.stroke();
  };

  const roundRect = (ctx, x, y, w, h, r) => {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const link = document.createElement('a');
    link.download = `gift-of-reading-${(userName || 'frame').replace(/\s+/g, '-')}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  return (
    <div style={{ textAlign: 'center', marginTop: 16 }}>
      <div
        style={{
          display: 'inline-block',
          maxWidth: '100%',
          borderRadius: 12,
          overflow: 'hidden',
          boxShadow: '0 20px 60px rgba(0,0,0,0.18)',
          background: '#fdfaf2'
        }}
      >
        <canvas
          ref={canvasRef}
          style={{
            display: 'block',
            width: '100%',
            maxWidth: 480,
            height: 'auto'
          }}
        />
      </div>

      <div style={{ marginTop: 24 }}>
        <button
          onClick={handleDownload}
          disabled={!isReady}
          style={{
            background: 'linear-gradient(135deg, #0d5d36 0%, #08442a 100%)',
            color: '#fff',
            border: 'none',
            padding: '14px 36px',
            borderRadius: 50,
            fontSize: '1rem',
            fontWeight: 600,
            cursor: isReady ? 'pointer' : 'not-allowed',
            opacity: isReady ? 1 : 0.6,
            boxShadow: '0 8px 20px rgba(13,93,54,0.3)',
            letterSpacing: '0.5px',
            transition: 'transform 0.2s'
          }}
          onMouseOver={(e) => isReady && (e.currentTarget.style.transform = 'translateY(-2px)')}
          onMouseOut={(e) => (e.currentTarget.style.transform = 'translateY(0)')}
        >
          ⬇ Download Frame
        </button>
      </div>
    </div>
  );
};

export default PhotoFrame;
